/** Durable DSH session journal contract (MET-221).
 *
 * `current` is the contract this build writes; `readsFrom` is the oldest one it
 * still reads. Raise `current` only for a breaking change (private payloads are
 * strict, so even a new field breaks one) and capture a corpus for it with
 * scripts/acceptance/runtime/capture-dsh-journal-v4.ts. Raising `readsFrom`
 * retires the older descriptors and corpora.
 *
 * native-journal-contract.surfaces.json holds the reviewed descriptor of every
 * readable version, generated by apps/worker/test/p25/native-journal-contract.test.ts
 * (`pnpm dsh:journal-contract -u`). A reviewed compatible change may update the
 * current version in place.
 *
 * A journal lives at <namespace>/<DSH project key of the tenant root>/<native
 * session id>/session.v4.jsonl, and the namespace starts at
 * ALLRICE_DSH_RUNTIME_ROOT: moving that root detaches every session. */
export const NATIVE_JOURNAL_CONTRACT = { current: 1, readsFrom: 1 } as const;
